import{_ as t}from"./chunks/settings-cal.pc.en.X2_AiM35.js";import{_ as o}from"./chunks/maintenance-pwr.pc.en.CVW_nHka.js";import{_ as a,o as r,c as i,a5 as n}from"./chunks/framework.D47SInms.js";const d="/RBQ/nightly/images/app/settings-chk.pc.en.png",s="/RBQ/nightly/images/app/maintenance-vision.pc.en.png",c="/RBQ/nightly/images/app/maintenance-ini.pc.en.png",k=JSON.parse('{"title":"Maintenance","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/maintenance.md","filePath":"manual/gui/maintenance.md","lastUpdated":1791600043000}'),h={name:"manual/gui/maintenance.md"};function l(p,e,b,m,u,f){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h1><p>Open <code>Maintenance</code> with its tile on the hub. The tile is shown to everyone and opens even without a robot connected; the sections that act on the robot need it connected. The sections sit as chips across the top:</p><ul><li><strong>Everyone:</strong> <code>Calibration</code>, <code>Robot Check</code>, <code>Software update</code> (covered in <a href="/RBQ/nightly/manual/gui/software-update.html">Software Update</a>), <code>Firmware update</code>.</li><li><strong><a href="/RBQ/nightly/manual/gui/developer-mode.html">Developer mode</a> only:</strong> <code>Power / System</code>, <code>Vision</code>, <code>Config file</code>, and — on robots with an arm — <code>Arm</code>. These can cut the connection, drop the robot or change how its daemons start — read each warning before you press anything.</li></ul><h2 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibration {#calibration}&quot;">​</a></h2><p><img src="'+t+'" alt="Calibration section"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Every calibration here must be run with the robot on flat ground and <strong>stationary</strong>. The IMU and ZMP rows are blocked while the robot is walking, has fallen, or is not reporting its state, and each one asks <code>Run calibration?</code> before it sends the command. <code>Joint home-pose setup</code> has its own confirmation. Do not touch the robot until the calibration has finished.</p></div><h3 id="imu-calibration" tabindex="-1">IMU Calibration <a class="header-anchor" href="#imu-calibration" aria-label="Permalink to &quot;IMU Calibration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Accelerometer calib (ACC)</code></td><td>Field correction of accelerometer drift. Run it <strong>while the robot is sitting</strong>, on level ground; it averages the gravity magnitude for about 2 s and stores the factor.</td></tr><tr><td><code>IMU roll/pitch zero</code></td><td>Makes the current posture the level reference. Takes about half a second — if the robot is tilted when you run it, all later control will be off.</td></tr><tr><td><code>Gyro Bias Calibration</code></td><td>Resets the IMU, waits for the values to settle, then measures the gyro again — about 5 s, <strong>while the robot is sitting</strong>. When it finishes it reports all three axes and whether each one is within the limit. If the bias is still over the limit, hold the robot completely still and run it again.</td></tr></tbody></table><p>Press <code>Run</code>, then confirm <code>Run</code> in the dialog. When a row is blocked, the app tells you why, and if it can clear the block itself, a button appears next to <code>Run</code>: <code>Sit</code> when the robot needs to sit, <code>Stand</code> when it needs to stand, and <code>Auto Start</code> when control is off, which asks first. You get no such button while the robot has fallen, is docking, or is not reporting.</p><p><code>IMU roll/pitch zero</code> shows the current roll and pitch under the level in its dialog. A progress dialog follows while it runs. It ends with <code>Success</code> only when roll and pitch both come back within 1° — if the robot is still tilted, it reads <code>The zero may not have taken effect</code> instead, and you put the robot on flat ground and run it again.</p><h3 id="zmp-calibration" tabindex="-1">ZMP Calibration <a class="header-anchor" href="#zmp-calibration" aria-label="Permalink to &quot;ZMP Calibration&quot;">​</a></h3><p><code>Auto-calibrate ZMP offset</code> finds the center-of-mass offset automatically. The robot must be in STAND on flat ground. It walks one step to square up its legs, then takes up to 60 s to converge. Once the offset converges, the robot saves it on its own and returns to STAND. The panel shows the progress and a completion message.</p><h3 id="joint-calibration" tabindex="-1">Joint Calibration <a class="header-anchor" href="#joint-calibration" aria-label="Permalink to &quot;Joint Calibration&quot;">​</a></h3><p>Re-establishes the leg joints&#39; zeros and offsets. Run it with the robot <strong>sitting</strong>.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Joint home-pose setup</code></td><td>Hold the home pose with the jig, then store it as the joint zero — four legs</td></tr><tr><td><code>DQ offset calibration</code></td><td><code>Not available yet</code> — the row is reserved and cannot be pressed</td></tr></tbody></table><p><code>Joint home-pose setup</code> opens two dialogs: first the notice (<em>This rewrites the joint zeros — running it without the jig, or with the pose off, leaves the robot booting on wrong zeros</em>), then the per-leg screen. On that screen, tap a joint card to see that joint move to its target pose in the 3D view on the left. Fit the jig, hold that pose, and press <code>Save LEG{n} {g} home pose</code> on that card — the roll card and the pitch/knee card each have their own button. Writing the zero switches control off (BOARD_RESET), so sit the robot down first — it will collapse if it is standing. The jig is required.</p><p>If the motor boards do not answer, the row is blocked with <em>No communication with the motor boards — turn the 48 V drive (LEGS) power on and run it again</em>; that rail is under <a href="#power">Power / System</a> on this page.</p><p>For the roll joint you pick the reference in the wizard: <code>Limit</code> pushes the joint against its inner limit as before, and <code>Level 0°</code> lets you make sure the body is level, set the joint to 0° with a bubble level, and shift the zero to match. Both references switch control off. The notice on closing offers <code>Auto Start</code> to bring the robot up again right away. If the correction is 9° or more, the robot rejects it and asks you to set the home against the limit first.</p><h3 id="camera-check" tabindex="-1">Camera Check · Calibration <a class="header-anchor" href="#camera-check" aria-label="Permalink to &quot;Camera Check · Calibration {#camera-check}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Basic Camera Check</code></td><td>Shows the views of the six cameras with their FPS. The views are not connected yet.</td></tr><tr><td><code>Lower Depth Camera On-chip Calibration</code></td><td>Opens the on-chip calibration notice for the lower depth cameras. Keep the robot standing on a flat floor. The calibration sequence itself is not available yet.</td></tr><tr><td><code>Lower Depth Camera Position Calibration</code></td><td>Asks you to install a marker board under the robot. The calibration itself is not available yet.</td></tr></tbody></table><h3 id="docking-calibration" tabindex="-1">Docking calibration <a class="header-anchor" href="#docking-calibration" aria-label="Permalink to &quot;Docking calibration&quot;">​</a></h3><p>The bottom of the Calibration section holds the auto-docking alignment parameters: <code>Offset X (m)</code>, <code>Offset Y (m)</code>, <code>Req Count</code>, <code>Try Count</code>.</p><ul><li><code>Reload</code> re-reads the values from the robot.</li><li><code>Defaults</code> fills the fields with factory defaults — nothing is saved until you press <code>Apply</code>.</li><li><code>Apply</code> writes the values to the robot and reads them back.</li></ul><h2 id="robot-check" tabindex="-1">Robot Check <a class="header-anchor" href="#robot-check" aria-label="Permalink to &quot;Robot Check {#robot-check}&quot;">​</a></h2><p><img src="'+d+'" alt="Robot Check section"></p><p><code>Robot Check</code> checks the robot&#39;s condition in order, from sitting to walking. Each stage is a card: press <code>Measure</code>, read the result, and if a value is out of range, fix it on the spot with the button next to it. The fix buttons work whether or not you have measured — they only follow the robot&#39;s state. An out-of-range value only marks the card <code>Caution</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Stages 4 and 5 move the robot by itself, and joystick input is ignored while they run. Clear 1 m around the robot before you start. <code>Stop</code> ends the run and the robot stands.</p></div><h3 id="gait-check" tabindex="-1">Gait Check <a class="header-anchor" href="#gait-check" aria-label="Permalink to &quot;Gait Check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stage</th><th>Robot</th><th>What it measures</th><th>Reference</th><th>Fix</th></tr></thead><tbody><tr><td>1 <code>Sitting · IMU</code></td><td>Sitting</td><td>Gravity magnitude and gyro bias, averaged over 3 s</td><td>9.75 ~ 9.85 m/s², gyro under 1.0 °/s</td><td><code>Accelerometer Calibration</code>, <code>Gyro Bias Calibration</code></td></tr><tr><td>2 <code>Motor Calibration Status</code></td><td>Sitting</td><td>Supported in a later update</td><td>—</td><td>—</td></tr><tr><td>3 <code>Standing · Level</code></td><td>Standing</td><td>Roll and pitch over 2 s, after you level the body by hand with a bubble level placed on it</td><td>±0.3°</td><td><code>IMU roll/pitch zero</code></td></tr><tr><td>4 <code>Joint Communication</code></td><td>Standing</td><td>CAN communication of each joint while the body twists left and right up to 30°, five times (about 10 s) — <code>Per motor</code>: missed frames, lowest receive rate, longest receive gap; <code>Per channel</code>: <code>Error frames</code>, <code>error-warning</code>, <code>error-passive</code>, <code>bus-off</code></td><td>450 Hz or more received, gaps of 10 ms or less</td><td>—</td></tr><tr><td>5 <code>Trot in place · Drift</code></td><td>Standing</td><td>Trots in place for 10 s, stands again, and compares the body position with the start</td><td>under ±10 cm fore-aft, under ±5 cm lateral</td><td><code>Visual Check</code>, then <code>Joint home-pose setup</code>, then <code>ZMP Calibration</code></td></tr></tbody></table><ul><li>Stage 4: if a joint is out of range, the card names the leg and asks you to check the wiring between the body and that leg module. Compare the missed frames between joints: a joint that misses frames while the others do not points to that leg&#39;s wiring. <code>Per channel</code> lists the CAN channels the legs are on, with the legs on each. <code>Error frames</code> counts how many times the channel reported a state change (error-warning, error-passive, bus-off or recovery) during the twist. These numbers are shown for reference and are not part of the verdict. The sim has no CAN measurement, so it is not judged there.</li><li>Stage 5: if the robot drifts 10 cm or more fore-aft or 5 cm or more sideways, the card marks every direction that drifted and recommends <code>Visual Check</code>, then <code>Joint home-pose setup</code>, then <code>ZMP Calibration</code>, in that order. The home-pose setup is the same wizard as in Calibration and needs the robot sitting — while it stands, a <code>Sit</code> button comes first.</li></ul><h3 id="camera-check-1" tabindex="-1">Camera Check <a class="header-anchor" href="#camera-check-1" aria-label="Permalink to &quot;Camera Check&quot;">​</a></h3><p>There are three stages: <code>Camera View · FPS</code>, <code>Depth Camera Quality</code>, <code>Depth Camera Alignment</code>. Measuring and judging are not available yet; the fix buttons open the same dialogs as <a href="#camera-check">Calibration › Camera Check · Calibration</a>.</p><h2 id="board-firmware" tabindex="-1">Firmware update <a class="header-anchor" href="#board-firmware" aria-label="Permalink to &quot;Firmware update {#board-firmware}&quot;">​</a></h2><p><code>Firmware update</code> updates the boards inside the robot (16 leg motors, PDU, IF, SIDE_F, SIDE_H and TOP) to the latest firmware files stored on the robot. It is a different section from <code>Software update</code>, which replaces the software on the robot PC. The robot reads each board&#39;s hw and picks the file for it. If the robot has no firmware file named with its hw for a kind of board, those boards are marked <code>Not managed</code> and skipped.</p><p>The 16 leg motors must all run the same firmware, so they are treated as one group. In the counts and lists on this screen the motors are one item (<code>Motors (n)</code>). A motor whose version matches but whose contents differ from the file is written again, and a banner appears at the top when the motors run different firmware. If any motor cannot be updated (for example a downgrade you did not agree to), the robot writes none of the motors and tells you why.</p><table tabindex="0"><thead><tr><th>Row</th><th>Effect</th></tr></thead><tbody><tr><td><code>Status</code></td><td>Counts the boards as <code>Updatable</code>, <code>Latest</code> and <code>Needs check</code>. The motor group counts as one. Boards that do not answer are counted as <code>no response</code>, and skipped boards as <code>Not managed</code>. <code>Check versions</code> makes the robot read the version and hw of every board again. It cannot be pressed while the robot is standing or walking.</td></tr><tr><td><code>Update all</code></td><td>Updates the boards that need it one at a time, in the order PDU → IF → SIDE_F → SIDE_H → TOP → leg motors. It opens a confirmation first.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Update all cuts leg and arm power first, and leg and arm power stay off when it finishes. Start the robot again afterwards. Leg power is turned on only while the leg motors are updated. UPC power goes off briefly while the PDU is updated, and the 12V ports while the TOP board is updated. An update can start only while the robot is sitting or its control is off, and only while it is sitting if the joints are under control. It can also start after an emergency stop as long as leg power is off (a TOP board without an hw record holds the emergency stop).</p></div><p>When <code>Update all</code> cannot be pressed, the reason appears under the row.</p><ul><li><code>The robot is active — sit it down and try again</code> — the robot is standing or walking. It also appears when the joints are under control but the robot is not sitting, such as during auto start.</li><li><code>Another device has control</code> — another device holds control of the robot.</li><li><code>Some boards need checking</code> — the robot has no file for a board, or does not know the board&#39;s hw and so cannot pick a file. The board name and the reason follow. While any such board exists, the whole update does not run.</li><li><code>No boards to update</code> — every board is up to date or <code>Not managed</code>.</li><li><code>The robot is busy with firmware work — try again when it has finished</code> — the robot is doing other firmware work.</li><li><code>The robot software does not support this — run Software update first</code></li></ul><p>A board left in boot does not block the update even if its hw is unknown. The robot sends that board to its app, reads the hw again and then updates it with the matching file. The update is not blocked either when leg power is off and no motor answers. The robot then turns leg power on during the update and checks the motors.</p><p>One confirmation dialog lists the boards and everything you agree to. If the legs or the arm are under control, a sentence says power will be cut first, and the button becomes <code>Cut power and update</code>. If a board would go down to an older version than the one it has, that board and both versions are named (the motors in one sentence), and a board that was running firmware for another variant gets a sentence saying it is switched to the matching variant. If the check ran with leg power off, the motors have no verdict and you cannot agree to a motor downgrade. To take the motors down, press <code>Check versions</code> again with leg power on. If the robot&#39;s check result changes after the dialog opened, the update is not sent and the dialog asks again with the changes.</p><p>While the update runs, the same place shows the steps (<code>48V off</code>, the board names, <code>Legs on</code>, <code>Motor</code>, <code>Legs off</code>). The board being written gets a progress bar, and a resend shows its count, such as <code>Retry 1/3</code>. There is no stop button, and the update keeps running on the robot even if you close the screen. At the end you see <code>Update complete — n boards</code> with a note that power is still off. If it fails, the reason appears and the robot stops with leg power off. When sending to a board fails, the robot tries again up to three more times after the first attempt. If those fail too, it leaves that board in boot and stops. Update again after a moment.</p><h3 id="board-firmware-banner" tabindex="-1">Top banners <a class="header-anchor" href="#board-firmware-banner" aria-label="Permalink to &quot;Top banners {#board-firmware-banner}&quot;">​</a></h3><p>These banners can appear at the top of the hub and other screens.</p><ul><li><code>Some boards need a firmware update (IF)</code> — a board was left in boot, or a board is on standby because its firmware does not support its hw. <code>Open</code> brings you to this section.</li><li><code>Motor firmware is mixed — run a firmware update</code> — the motors differ in firmware version or verdict. <code>Open</code> brings you to this section.</li><li><code>Some boards need an hw record — contact an administrator</code> — a board is on standby because no hw is recorded on it. An update does not clear this.</li><li><code>A board is on standby because its EEPROM does not respond — contact an administrator</code> — the board cannot read its hw and is on standby. An update does not clear this.</li></ul><p>The X on the right of a banner closes it. It comes back when a different board is affected or when you reconnect to the robot.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#board-firmware">Developer mode</a>.</p></blockquote><h2 id="power" tabindex="-1">Power / System <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power / System {#power}&quot;">​</a></h2><p><img src="'+o+'" alt="Power / System section"></p><p>This section exposes every PDU rail, including the ones deliberately kept out of Settings. Toggles show the real rail state from the robot; they are disabled until that state has been received.</p><p><strong>12 V toggles</strong> (one tap): <code>Speaker amp (12V)</code>, <code>LiDAR (12V)</code>, <code>CCTV (12V)</code>, <code>Thermal (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>Rails that break the link</strong> (two-step confirmation <code>Turn this off?</code> → <code>Turn off</code>; the dialog has a <code>Don&#39;t ask for a day</code> checkbox — once ticked, that rail switches without confirmation for 24 hours on this screen only; Settings → Power always confirms):</p><table tabindex="0"><thead><tr><th>Rail</th><th>Effect of switching off</th></tr></thead><tbody><tr><td><code>Cameras (5V)</code></td><td>Video stops.</td></tr><tr><td><code>Audio·USB hub (5V)</code></td><td>Audio devices disappear.</td></tr><tr><td><code>Vision PC (12V)</code></td><td>Cameras, audio and part of the telemetry on this screen stop.</td></tr><tr><td><code>Comm (12V)</code></td><td>The app&#39;s own connection to the robot is lost.</td></tr></tbody></table><p><strong>48 V drive rails</strong> (two-step, live voltage shown):</p><table tabindex="0"><thead><tr><th>Rail</th><th>Notes</th></tr></thead><tbody><tr><td><code>LEGS (48V drive)</code></td><td>Leg motor power. Can only be switched off while the robot is not standing (sitting, control off or fallen); the row is blocked otherwise.</td></tr><tr><td><code>ARM · ADDON (48V)</code></td><td>Arm and add-on power — one port for both. Confirm the arm is stopped first.</td></tr><tr><td><code>EXTERN (48V)</code></td><td>External expansion port power.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Switching <code>LEGS (48V drive)</code> off makes the robot collapse. <code>System reboot</code> — <code>Reboot</code> → <code>Reboot the robot PC?</code> → <code>Reboot</code> — restarts the robot PC: the robot loses motor power and the app connection drops for the duration. Sit the robot on the floor before either action. The reboot dialog also has the <code>Don&#39;t ask for a day</code> checkbox.</p></div><p>On CAN-FD robots the rails above are replaced by individual PDU ports in four groups — <code>12V ports</code>, <code>Camera power (USB)</code>, <code>Audio</code>, <code>⚠ 48V drive rails — dangerous action</code> — each row showing its live state, voltage and current. <code>Comm (12V · WAN)</code>, the camera ports and the 48 V ports confirm in two steps; <code>LEGS (48V drive)</code> is blocked while standing as above; <code>PDU (48V battery rail)</code> is display only. <code>Inputs · Battery · Temperature</code> below lists the charger inputs, both battery packs and the board temperatures. Between <code>Audio</code> and the 48 V group sits <code>Bottom status LEDs (IF board)</code>, the same as in <a href="/RBQ/nightly/manual/gui/settings.html#power">Settings › Power</a>; what its dialog adds in developer mode is on <a href="/RBQ/nightly/manual/gui/developer-mode.html#what-changes">Developer mode</a>.</p><p>Below the 48 V rails the section repeats the <code>Accelerometer calib (ACC)</code> and <code>IMU roll/pitch zero</code> rows described in <a href="#calibration">Maintenance → Calibration</a>; they behave the same here.</p><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p><img src="'+s+'" alt="Vision section"></p><p>Vision toggles — night mode, stealth, IR projector, video resolution and the rest — are in the <code>Vision</code> popover on the control screen; see <a href="/RBQ/nightly/manual/gui/camera-vision.html">Camera &amp; Vision</a>. This section holds the developer tools.</p><p><code>Camera Calibration</code>:</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Jig Extrinsic Calibration</code></td><td>Calibrates each sensor&#39;s base↔sensor transform from the jig markers. The robot must be seated on the calibration jig. The result is written to the HAL settings.</td></tr><tr><td><code>OAK-D Intrinsic Calibration</code></td><td>Calibrates the front and rear stereo cameras while walking. The front camera must face a ChArUco board within 1 m. The result is written to each camera&#39;s EEPROM.</td></tr></tbody></table><p><code>Run</code> opens a confirmation that lists what to check first; progress and the result appear in the top banner. While a calibration runs, both buttons change to <code>Cancel</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The OAK-D intrinsic calibration makes the robot walk around by itself for about 10 minutes. Keep 1.5 m around the robot clear before starting it.</p></div><p><code>Daemon control</code> — <code>VISION RESET</code> → <code>Reset</code> has the Handler restart HAL, restarting the camera pipeline cleanly. Video drops for a few seconds; the button shows <code>Resetting…</code> and stays unavailable for about 8 seconds.</p><p><code>Vision Programs</code> lets you start and stop individual vision daemons by hand (<code>Vision</code>, <code>HAL</code>, <code>Streamer</code>, <code>Handeye</code>, <code>Heightmap</code>, <code>Cctv</code>, <code>Ptz</code>, <code>Thermal</code>). Their on/off state comes from the robot&#39;s reported program status; only on older daemons that do not report it does it fall back to the last command sent.</p><h2 id="config-file" tabindex="-1">Config file <a class="header-anchor" href="#config-file" aria-label="Permalink to &quot;Config file&quot;">​</a></h2><p><img src="'+c+'" alt="Config file section"></p><p>The INI editor edits the robot daemons&#39; configuration files directly. The target selector switches between <code>Motion.ini</code>, <code>HAL · config.ini</code>, <code>Handler · config.ini</code> and <code>Streamer.ini</code>. Use <code>Search key</code> to filter keys; boolean values can be toggled, other values are edited in place. The header shows how many sections were read and when.</p><p>The footer counts unsaved edits (<code>{n} changes</code>). <code>Revert</code> discards them, <code>Reload</code> re-reads the file from the robot, <code>Save</code> opens the confirmation <code>Save to {label}?</code> listing every changed key with its old and new value.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Saving replaces the <strong>entire</strong> file on the robot with what the editor holds — always edit on top of a freshly loaded file. Changes apply only after the corresponding daemon (Motion, HAL, Handler or Streamer) is restarted; the app does not restart it for you. Do not change values whose meaning you do not know.</p></div><h2 id="arm" tabindex="-1">Arm <a class="header-anchor" href="#arm" aria-label="Permalink to &quot;Arm&quot;">​</a></h2><p>Shown only when the robot reports an arm. This section is the initial bring-up.</p><ol><li>Press <code>CAN check</code>, <code>Release brake</code>, <code>Control Start</code> in that order. Wait for the status badge to light up after each step before pressing the next. ▶ Auto Start ARM runs the whole sequence in one press.</li><li><code>Static poses</code> sends a fixed pose (<code>Straight</code>, <code>Folding</code>, <code>Ready</code>, <code>Lift</code>, <code>Packing</code>, <code>DoorReady</code>) without a trajectory — on the first use start from <code>Ready</code>.</li><li><code>Joint lock / jog</code> — tap a joint card to lock or unlock it; hold <code>+</code> / <code>−</code> to jog a locked joint (the buttons are disabled while the joint is unlocked).</li></ol><p>RC01 / RC02 attachment sections are not covered by this manual.</p>',76)])])}const v=a(h,[["render",l]]);export{k as __pageData,v as default};
